/*
  src/index.js
  -------------
  The very first file React runs.

  What it does:
    1. Finds the <div id="root"> in public/index.html
    2. Mounts our <App /> component inside it
    3. React takes over — all UI updates happen in JS

  You almost never need to edit this file.
*/

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

// Find the <div id="root"> in public/index.html
const root = ReactDOM.createRoot(document.getElementById('root'));

// Render our App component into it
root.render(
  <React.StrictMode>
    {/*
      StrictMode:
      - Only in development
      - Runs effects twice to help find bugs
      - Shows warnings about deprecated features
      - Has NO effect in production
    */}
    <App />
  </React.StrictMode>
);
